1	function isSlashCommandPrompt(prompt: string): boolean {
2	  const trimmed = prompt.trimStart();
3	  if (!trimmed.startsWith('/')) return false;
4	
5	  const match = /^\/([^\s/]+)(?:\s|$)/.exec(trimmed);
6	  if (!match) return false;
7	
8	  return true;
9	}
